import{_ as e,o as a,c as t,a4 as o}from"./chunks/framework.B-3VpRq4.js";const m=JSON.parse('{"title":"备赛资料","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function l(s,r,n,h,d,c){return a(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="备赛资料" tabindex="-1">备赛资料 <a class="header-anchor" href="#备赛资料" aria-label="Permalink to &quot;备赛资料&quot;">​</a></h1><blockquote><p>📚 系统化整理的 RoboMaster 备赛资料，覆盖机械、电控、视觉、算法四大方向</p></blockquote><hr><h2 id="🗺️-学习路线图" tabindex="-1">🗺️ 学习路线图 <a class="header-anchor" href="#🗺️-学习路线图" aria-label="Permalink to &quot;🗺️ 学习路线图&quot;">​</a></h2><h3 id="新人入门路径" tabindex="-1">新人入门路径 <a class="header-anchor" href="#新人入门路径" aria-label="Permalink to &quot;新人入门路径&quot;">​</a></h3><div class="timeline"><div class="timeline-item"><strong>第 1 步：了解 RM</strong><p>阅读 <a href="https://www.robomaster.com/zh-CN" target="_blank">RoboMaster 官网</a>，观看比赛视频，了解比赛规则和机器人兵种</p></div><div class="timeline-item"><strong>第 2 步：选择方向</strong><p>根据兴趣和基础选择机械/电控/视觉/算法方向，每个方向都有不同的技能要求</p></div><div class="timeline-item"><strong>第 3 步：环境搭建</strong><p>根据所选方向搭建开发环境（IDE、工具链、仿真平台等）</p></div><div class="timeline-item"><strong>第 4 步：基础学习</strong><p>学习该方向的基础知识，完成入门小项目</p></div><div class="timeline-item"><strong>第 5 步：实战练习</strong><p>参与战队项目，在实战中成长</p></div></div><hr><h2 id="四大方向" tabindex="-1">四大方向 <a class="header-anchor" href="#四大方向" aria-label="Permalink to &quot;四大方向&quot;">​</a></h2><div class="rm-card"><h3 id="🛠️-机械方向-→" tabindex="-1">🛠️ <a href="/arkrobomaster/guide/mechanical">机械方向 →</a> <a class="header-anchor" href="#🛠️-机械方向-→" aria-label="Permalink to &quot;🛠️ [机械方向 →](/guide/mechanical)&quot;">​</a></h3><ul><li><strong>核心技能</strong>：SolidWorks 建模、材料力学、机械原理、有限元分析</li><li><strong>工作内容</strong>：机器人底盘/云台/发射机构设计、减重优化、加工装配</li><li><strong>推荐工具</strong>：SolidWorks, AutoCAD, ANSYS</li></ul></div><div class="rm-card"><h3 id="⚡-电控方向-→" tabindex="-1">⚡ <a href="/arkrobomaster/guide/electronics">电控方向 →</a> <a class="header-anchor" href="#⚡-电控方向-→" aria-label="Permalink to &quot;⚡ [电控方向 →](/guide/electronics)&quot;">​</a></h3><ul><li><strong>核心技能</strong>：STM32 开发、嵌入式 C 语言、PID 控制、CAN 通信</li><li><strong>工作内容</strong>：电机驱动、传感器读取、遥控器通信、底盘/云台控制</li><li><strong>推荐工具</strong>：Keil/STM32CubeIDE, J-Link, 示波器</li></ul></div><div class="rm-card"><h3 id="👁️-视觉方向-→" tabindex="-1">👁️ <a href="/arkrobomaster/guide/vision">视觉方向 →</a> <a class="header-anchor" href="#👁️-视觉方向-→" aria-label="Permalink to &quot;👁️ [视觉方向 →](/guide/vision)&quot;">​</a></h3><ul><li><strong>核心技能</strong>：OpenCV、目标检测（YOLO）、相机标定、C++/Python</li><li><strong>工作内容</strong>：装甲板识别、能量机关击打、自动瞄准、双目测距</li><li><strong>推荐工具</strong>：OpenCV, YOLOv8/v11, CMake, Ubuntu</li></ul></div><div class="rm-card"><h3 id="🧠-算法方向-→" tabindex="-1">🧠 <a href="/arkrobomaster/guide/algorithm">算法方向 →</a> <a class="header-anchor" href="#🧠-算法方向-→" aria-label="Permalink to &quot;🧠 [算法方向 →](/guide/algorithm)&quot;">​</a></h3><ul><li><strong>核心技能</strong>：ROS2、路径规划、运动控制、卡尔曼滤波</li><li><strong>工作内容</strong>：哨兵导航、决策树、状态机、仿真模拟</li><li><strong>推荐工具</strong>：ROS2, Gazebo, Eigen, Ceres</li></ul></div><hr><h2 id="📖-推荐资源" tabindex="-1">📖 推荐资源 <a class="header-anchor" href="#📖-推荐资源" aria-label="Permalink to &quot;📖 推荐资源&quot;">​</a></h2><h3 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h3><ul><li><a href="https://www.robomaster.com/" target="_blank" rel="noreferrer">RoboMaster 官网</a></li><li><a href="https://bbs.robomaster.com/" target="_blank" rel="noreferrer">RoboMaster 官方论坛</a></li><li><a href="https://github.com/robomaster-oss" target="_blank" rel="noreferrer">RoboMaster OSS (官方开源)</a></li><li><a href="https://www.robomaster.com/zh-CN/products/components/referee" target="_blank" rel="noreferrer">RoboMaster 裁判系统手册</a></li></ul><h3 id="社区资源" tabindex="-1">社区资源 <a class="header-anchor" href="#社区资源" aria-label="Permalink to &quot;社区资源&quot;">​</a></h3><ul><li><a href="https://github.com/OpenRoboMaster/awesome-robomaster" target="_blank" rel="noreferrer">Awesome RoboMaster</a> — RM 领域开源项目大全</li><li><a href="https://sjtu-robomaster-team.github.io/" target="_blank" rel="noreferrer">上海交大交龙战队博客</a> — 优秀技术博客参考</li><li><a href="https://rm-static.djicdn.com/tem/13194/RoboMaster%20%E5%8F%82%E8%B5%9B%E6%94%BB%E7%95%A5.pdf" target="_blank" rel="noreferrer">RM 参赛攻略 (官方 PDF)</a></li></ul><h3 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h3><ul><li><strong>C++</strong>：《C++ Primer》、<a href="https://www.learncpp.com/" target="_blank" rel="noreferrer">learncpp.com</a></li><li><strong>ROS2</strong>：<a href="https://docs.ros.org/" target="_blank" rel="noreferrer">ROS2 官方文档</a></li><li><strong>OpenCV</strong>：<a href="https://docs.opencv.org/" target="_blank" rel="noreferrer">OpenCV 官方教程</a></li><li><strong>SolidWorks</strong>：B站教程 + 实践项目</li></ul>',20)])])}const b=e(i,[["render",l]]);export{m as __pageData,b as default};
